import{_ as t,o as a,c as r,a7 as o}from"./chunks/framework.C4ZIv4ii.js";const u=JSON.parse('{"title":"Navigation & Managing","description":"","frontmatter":{},"headers":[],"relativePath":"slider/navigation.md","filePath":"slider/navigation.md","lastUpdated":1785395078000}'),s={name:"slider/navigation.md"};function i(n,e,l,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="navigation-managing" tabindex="-1">Navigation &amp; Managing <a class="header-anchor" href="#navigation-managing" aria-label="Permalink to &quot;Navigation &amp; Managing&quot;">​</a></h1><p>This page covers how visitors move between slides — arrows, bullets, progress, thumbnails and autoplay — plus the productivity tools that keep your work safe: version history, full-screen preview, templates and import/export.</p><hr><h2 id="autoplay" tabindex="-1">Autoplay <a class="header-anchor" href="#autoplay" aria-label="Permalink to &quot;Autoplay&quot;">​</a></h2><p>In the slider <strong>Settings</strong> tab:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Autoplay</strong></td><td>Advance slides automatically</td></tr><tr><td><strong>Autoplay delay</strong></td><td>Time each slide stays (ms)</td></tr><tr><td><strong>Loop</strong></td><td>Return to the first slide after the last</td></tr><tr><td><strong>Pause on hover</strong></td><td>Stop autoplay while the pointer is over the slider</td></tr></tbody></table><hr><h2 id="navigation-controls" tabindex="-1">Navigation controls <a class="header-anchor" href="#navigation-controls" aria-label="Permalink to &quot;Navigation controls&quot;">​</a></h2><h3 id="arrows" tabindex="-1">Arrows <a class="header-anchor" href="#arrows" aria-label="Permalink to &quot;Arrows&quot;">​</a></h3><p>Previous / next arrows. Choose a <strong>style</strong>, a <strong>position</strong> (e.g. middle), and fine-tune the <strong>x / y</strong> offset. Toggle on or off.</p><h3 id="bullets" tabindex="-1">Bullets <a class="header-anchor" href="#bullets" aria-label="Permalink to &quot;Bullets&quot;">​</a></h3><p>Dot navigation for jumping to any slide. Choose a <strong>style</strong>, a <strong>position</strong> (e.g. bottom-centre) and <strong>x / y</strong> offset.</p><h3 id="progress-bar" tabindex="-1">Progress bar <a class="header-anchor" href="#progress-bar" aria-label="Permalink to &quot;Progress bar&quot;">​</a></h3><p>An optional bar that fills as each slide plays. Set its <strong>colour</strong>, <strong>height</strong> and <strong>position</strong> (top or bottom).</p><h3 id="thumbnails" tabindex="-1">Thumbnails <a class="header-anchor" href="#thumbnails" aria-label="Permalink to &quot;Thumbnails&quot;">​</a></h3><p>Show a strip of slide thumbnails for direct navigation — great for showcases where visitors pick what to view.</p><h3 id="spinner-preloader" tabindex="-1">Spinner / preloader <a class="header-anchor" href="#spinner-preloader" aria-label="Permalink to &quot;Spinner / preloader&quot;">​</a></h3><p>Optionally show a <strong>spinner</strong> that covers the stage until the first slide&#39;s background is ready, so visitors never see a half-loaded slide.</p><hr><h2 id="sizing" tabindex="-1">Sizing <a class="header-anchor" href="#sizing" aria-label="Permalink to &quot;Sizing&quot;">​</a></h2><p>The slider <strong>Settings</strong> tab offers three sizing modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>Fixed design width, centred on the page (e.g. 1200 × 600)</td></tr><tr><td><strong>Full-width</strong></td><td>Spans the full document width; keeps the design height</td></tr><tr><td><strong>Full-screen</strong></td><td>Fills the entire viewport (100vh)</td></tr></tbody></table><p>Full-width and full-screen break out of the theme&#39;s container automatically and are sized to the document width (never causing a horizontal scrollbar). The design <strong>width / height</strong> and the <strong>tablet / mobile</strong> breakpoints are all set here too.</p><hr><h2 id="version-history" tabindex="-1">Version history <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version history&quot;">​</a></h2><p>Every time you <strong>Save</strong>, Falcon Slider automatically stores a snapshot of the design. The most recent <strong>20 versions</strong> are kept per slider.</p><p>To restore one:</p><ol><li>Click <strong>Revisions</strong> in the toolbar</li><li>Pick a version from the list (each shows <em>when</em> it was saved and how many slides it had)</li><li>Click <strong>Restore</strong> — that version loads into the editor</li></ol><div class="tip custom-block"><p class="custom-block-title">Restore is safe</p><p>Restoring loads the old version <em>into the editor</em> as an undoable step — nothing becomes permanent until you <strong>Save</strong>. Review the restored design first, then keep it or undo.</p></div><hr><h2 id="full-screen-live-preview" tabindex="-1">Full-screen live preview <a class="header-anchor" href="#full-screen-live-preview" aria-label="Permalink to &quot;Full-screen live preview&quot;">​</a></h2><p>Click <strong>Preview</strong> in the toolbar to open a full-screen preview of your <strong>current, unsaved</strong> design. Autoplay runs and every animation, reveal and idle loop plays exactly as it will on the live site.</p><ul><li>It renders your in-editor state — no need to save first.</li><li><strong>Reload</strong> re-renders with your latest changes.</li><li><strong>Exit</strong> (or <strong>Esc</strong>) closes it.</li><li>Nothing is written to the database — it&#39;s a pure preview.</li></ul><hr><h2 id="templates-the-pre-built-gallery" tabindex="-1">Templates &amp; the pre-built gallery <a class="header-anchor" href="#templates-the-pre-built-gallery" aria-label="Permalink to &quot;Templates &amp; the pre-built gallery&quot;">​</a></h2><h3 id="pre-built-sliders" tabindex="-1">Pre-built sliders <a class="header-anchor" href="#pre-built-sliders" aria-label="Permalink to &quot;Pre-built sliders&quot;">​</a></h3><p>Click <strong>Pre-built Sliders</strong> to open a gallery of ready-made designs. Applying one drops its slides and settings straight into your slider — a fast starting point.</p><h3 id="save-as-pre-built" tabindex="-1">Save as pre-built <a class="header-anchor" href="#save-as-pre-built" aria-label="Permalink to &quot;Save as pre-built&quot;">​</a></h3><p>Made a design worth reusing? Click <strong>Save as pre-built</strong> to store the current slider (settings + slides) as a reusable template in your library, under a category you name. It then appears in the Pre-built gallery for any future slider.</p><hr><h2 id="import-export" tabindex="-1">Import &amp; export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; export&quot;">​</a></h2><p>From the <strong>Falcon Slider</strong> admin list:</p><ul><li><strong>Export</strong> — download a single slider as a portable <code>.falconslider.json</code> file.</li><li><strong>Bulk export</strong> — select several sliders and download them as one bundle.</li><li><strong>Import</strong> — upload a single export <em>or</em> a bundle to recreate the slider(s) on this site.</li><li><strong>Duplicate</strong> — clone a whole slider (settings + all slides) as a new draft in one click.</li></ul><p>This makes it easy to move sliders between sites or keep off-site backups.</p><hr><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Access to Falcon Slider is governed by the <strong><code>manage_sliders</code></strong> permission and a valid Pro license. Grant the permission to a role under <a href="/falconcms/guide/rbac.html">Roles &amp; Permissions</a> to let other users build sliders.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/falconcms/slider/overview.html">Overview</a> — what Falcon Slider is and how to embed it</li><li><a href="/falconcms/slider/slides.html">Slides &amp; Backgrounds</a></li><li><a href="/falconcms/slider/layers.html">Layers</a></li><li><a href="/falconcms/slider/animations.html">Animations</a></li></ul>',50)])])}const c=t(s,[["render",i]]);export{u as __pageData,c as default};
